//! Markdown to HTML conversion.
//!
//! The reference implementation renders CommonMark with a specific set of
//! extensions enabled (tables, strikethrough, autolinks, task lists, footnotes,
//! description lists, header anchors, wiki links, spoilers, GitHub alerts and
//! `:emoji:` shortcodes) and passes raw HTML through unescaped.

mod block;
mod inline;

/// A heading collected while rendering, used to build the table of contents.
#[derive(Debug, Clone)]
pub struct Heading {
    /// 1-6.
    pub level: u8,
    /// The anchor id assigned to the heading.
    pub id: String,
    /// The heading's rendered inline content, exactly as it appears inside the
    /// `<hN>` element (after the anchor element).
    pub html: String,
}

#[derive(Debug, Default)]
pub struct Output {
    pub html: String,
    pub headings: Vec<Heading>,
}

/// Render markdown to HTML.
pub fn render(markdown: &str) -> Output {
    block::render(markdown)
}

/// Convenience wrapper returning only the HTML.
pub fn to_html(markdown: &str) -> String {
    render(markdown).html
}

/// Build the table-of-contents markup from collected headings.
pub fn toc(headings: &[Heading]) -> String {
    block::toc(headings)
}
