"""Quick probe: render markdown bodies (given as a python dict or list from stdin/args) via reference."""
import os, shutil, subprocess, sys, re, json
BIN="/tmp/orig/marmite_ref"
S,E="@@@S@@@","@@@E@@@"
def render_many(bodies, fm_tpl="---\ntitle: T\nslug: %s\n---\n", tpl="{{ content.html }}", extra=None, config=None):
    """bodies: dict name->body. returns dict name->html"""
    WORK="/tmp/mdA/askwork"
    if os.path.exists(WORK): shutil.rmtree(WORK)
    os.makedirs(WORK+"/content"); os.makedirs(WORK+"/templates")
    open(WORK+"/templates/content.html","w").write(S+tpl+E)
    open(WORK+"/templates/list.html","w").write("")
    open(WORK+"/templates/group.html","w").write("")
    for k,v in bodies.items():
        fm = fm_tpl % k if "%s" in fm_tpl else fm_tpl
        open(WORK+"/content/"+k+".md","w").write(fm+v)
    if extra:
        for p,c in extra.items():
            fp=os.path.join(WORK,p); os.makedirs(os.path.dirname(fp),exist_ok=True); open(fp,"w").write(c)
    if config is not None: open(WORK+"/marmite.yaml","w").write(config)
    p=subprocess.run([BIN,".","out"],cwd=WORK,capture_output=True,text=True)
    res={}
    for k in bodies:
        fp=WORK+"/out/"+k+".html"
        if not os.path.exists(fp): res[k]=None; continue
        s=open(fp).read()
        m=re.search(re.escape(S)+"(.*)"+re.escape(E),s,re.S)
        res[k]=m.group(1) if m else "RAW:"+s
    return res,p
def show(bodies,**kw):
    if isinstance(bodies,(list,tuple)):
        bodies={"c%03d"%i:b for i,b in enumerate(bodies)}
    res,p=render_many(bodies,**kw)
    for k in bodies:
        print("="*60); print("IN  :",repr(bodies[k])); print("OUT :",repr(res[k]))
    errs=[l for l in (p.stdout+p.stderr).splitlines() if "ERROR" in l or "WARN" in l]
    for e in errs[:6]: print("LOG:",e)
    return res
